"use strict";(self.webpackChunkdocs_site=self.webpackChunkdocs_site||[]).push([["924"],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Stage A","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"overviewSidebar":[{"type":"link","href":"/","label":"Overview","docId":"overview/index","unlisted":false},{"type":"link","href":"/overview/plan","label":"Plan","docId":"overview/plan","unlisted":false}],"dataSidebar":[{"type":"link","href":"/data/","label":"Layer 1 \u2014 Data","docId":"data/index","unlisted":false}],"componentsSidebar":[{"type":"link","href":"/components/","label":"Layer 2 \u2014 Components","docId":"components/index","unlisted":false}],"businessLogicSidebar":[{"type":"link","href":"/business-logic/","label":"Layer 3 \u2014 Business Logic","docId":"business-logic/index","unlisted":false}],"apiSidebar":[{"type":"link","href":"/api/","label":"Overview","docId":"api/index","unlisted":false},{"type":"category","label":"User Actions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/api/user-actions/platform","label":"Platform","docId":"api/user-actions/platform","unlisted":false},{"type":"link","href":"/api/user-actions/purchase-orders","label":"Purchase Orders","docId":"api/user-actions/purchase-orders","unlisted":false},{"type":"link","href":"/api/user-actions/work-orders","label":"Work Orders","docId":"api/user-actions/work-orders","unlisted":false},{"type":"link","href":"/api/user-actions/sales-orders","label":"Sales Orders","docId":"api/user-actions/sales-orders","unlisted":false},{"type":"link","href":"/api/user-actions/materials-inventory","label":"Materials Inventory","docId":"api/user-actions/materials-inventory","unlisted":false},{"type":"link","href":"/api/user-actions/finished-goods-inventory","label":"Finished Goods Inventory","docId":"api/user-actions/finished-goods-inventory","unlisted":false},{"type":"link","href":"/api/user-actions/customers","label":"Customers","docId":"api/user-actions/customers","unlisted":false},{"type":"link","href":"/api/user-actions/products","label":"Products","docId":"api/user-actions/products","unlisted":false},{"type":"link","href":"/api/user-actions/bom","label":"Bill of Materials","docId":"api/user-actions/bom","unlisted":false},{"type":"link","href":"/api/user-actions/vendors","label":"Vendors","docId":"api/user-actions/vendors","unlisted":false},{"type":"link","href":"/api/user-actions/materials","label":"Materials","docId":"api/user-actions/materials","unlisted":false},{"type":"link","href":"/api/user-actions/locations","label":"Locations","docId":"api/user-actions/locations","unlisted":false},{"type":"link","href":"/api/user-actions/contacts","label":"Contacts","docId":"api/user-actions/contacts","unlisted":false},{"type":"link","href":"/api/user-actions/reporting","label":"Reporting","docId":"api/user-actions/reporting","unlisted":false}],"href":"/api/user-actions/"}],"clientsSidebar":[{"type":"link","href":"/clients/","label":"Layer 5 \u2014 Clients","docId":"clients/index","unlisted":false}]},"docs":{"api/index":{"id":"api/index","title":"Overview","description":"A single public API service. Versioned contract. Every user action from the frontend \u2014 write or read \u2014 maps to an endpoint here. Each endpoint calls into one or more L3 workflows; no endpoint reaches Layer 2 directly.","sidebar":"apiSidebar"},"api/user-actions/bom":{"id":"api/user-actions/bom","title":"Bill of Materials","description":"Covers BOMs \u2014 the composition that links input materials and/or input SKUs (with quantities) to an output SKU. A BOM is a recipe: one entry per output SKU. Read by cost-cascade and WO workflows; written from the BOM editor.","sidebar":"apiSidebar"},"api/user-actions/contacts":{"id":"api/user-actions/contacts","title":"Contacts","description":"Covers the shared contacts pool \u2014 people (with optional email/phone methods) that can be linked to customers, vendors, or other entities. The same contact can be reused across multiple entities, each link carrying its own role and notes.","sidebar":"apiSidebar"},"api/user-actions/customers":{"id":"api/user-actions/customers","title":"Customers","description":"Covers customers, the master-data tables that classify them (customer types, customer segments), and brokers (reusable broker entities used on customers and SOs).","sidebar":"apiSidebar"},"api/user-actions/finished-goods-inventory":{"id":"api/user-actions/finished-goods-inventory","title":"Finished Goods Inventory","description":"Covers the finished-goods inventory ledger (every movement of finished SKUs in/out/between locations) and the derived summary view (current stock by SKU \xd7 location). Most ledger entries are written automatically by SO operations (DEMAND / ALLOCATE / CONSUME) and WO operations (RECEIVE on completion); direct ledger writes are used for manual transfers, adjustments, and disposals.","sidebar":"apiSidebar"},"api/user-actions/index":{"id":"api/user-actions/index","title":"User Actions","description":"This is the catalog of every action a user can take in the platform today \u2014 both writes (create, update, delete) and reads (lists, lookups, detail views). It\'s the source of truth that everything downstream in the design phase builds on:","sidebar":"apiSidebar"},"api/user-actions/locations":{"id":"api/user-actions/locations","title":"Locations","description":"Covers fulfillment locations \u2014 warehouses / fulfillment centers / work sites. The same entity is reused as PO ship-to, WO work site, SO fulfillment location, and inventory bin across materials and finished goods.","sidebar":"apiSidebar"},"api/user-actions/materials":{"id":"api/user-actions/materials","title":"Materials","description":"Covers materials (raw inputs consumed by work orders or purchased on materials POs) and their type table.","sidebar":"apiSidebar"},"api/user-actions/materials-inventory":{"id":"api/user-actions/materials-inventory","title":"Materials Inventory","description":"Covers the materials inventory ledger (every movement of raw materials in/out/between locations) and the derived summary view (current stock by material \xd7 location). Most ledger entries are written automatically by PO receipts (RECEIVE) and WO operations (CONSUME); direct ledger writes are used for manual transfers, adjustments, and disposals.","sidebar":"apiSidebar"},"api/user-actions/platform":{"id":"api/user-actions/platform","title":"Platform","description":"Covers authentication, organizations, organization users, and invitations. The shared contacts pool is documented separately in Contacts.","sidebar":"apiSidebar"},"api/user-actions/products":{"id":"api/user-actions/products","title":"Products","description":"Covers SKUs (finished goods) and their type table. Materials and BOMs each have their own page; see Materials and Bill of Materials.","sidebar":"apiSidebar"},"api/user-actions/purchase-orders":{"id":"api/user-actions/purchase-orders","title":"Purchase Orders","description":"Covers purchase orders (PO), PO items, PO receipts, and PO status types. POs target either materials (raw inputs) or finished goods (resale), set on creation. Receipts drive the materials or finished-goods inventory ledger.","sidebar":"apiSidebar"},"api/user-actions/reporting":{"id":"api/user-actions/reporting","title":"Reporting","description":"Covers cross-domain views: the home dashboard (KPIs spanning orders + inventory + master data).","sidebar":"apiSidebar"},"api/user-actions/sales-orders":{"id":"api/user-actions/sales-orders","title":"Sales Orders","description":"Covers sales orders (SO), SO items, SO timeline notes, SO documents, and the SO-side master data (order channels, order status types, fulfillment status types). SO operations also drive the finished-goods inventory ledger (DEMAND / ALLOCATE / CONSUME events).","sidebar":"apiSidebar"},"api/user-actions/vendors":{"id":"api/user-actions/vendors","title":"Vendors","description":"Covers vendors \u2014 master data for the suppliers that POs are placed against. Vendor contacts are managed through the shared contacts pool (see Platform).","sidebar":"apiSidebar"},"api/user-actions/work-orders":{"id":"api/user-actions/work-orders","title":"Work Orders","description":"Covers work orders (WO), WO items, WO receipts, and WO status types. WOs convert materials into finished goods at a work site (a fulfillment location). Operations drive both the materials inventory ledger (consumption) and the finished-goods inventory ledger (production).","sidebar":"apiSidebar"},"business-logic/index":{"id":"business-logic/index","title":"Layer 3 \u2014 Business Logic","description":"A single template \u2014 Anthem \u2014 runs the show. Every workflow, every constraint, every validation behind a user action lives here. J&B and the variant/extension model belong to later stages.","sidebar":"businessLogicSidebar"},"clients/index":{"id":"clients/index","title":"Layer 5 \u2014 Clients","description":"The web app is the only client in Stage A. It becomes a thin client \u2014 local logic (aggregations, derived state, N+1 fetches) moves into the backend behind L4 endpoints. No new client surfaces (mobile, desktop, CLI, AI agents, partner integrations) in this stage.","sidebar":"clientsSidebar"},"components/index":{"id":"components/index","title":"Layer 2 \u2014 Components","description":"Stateless modules \u2014 one per domain \u2014 running in-process inside the single backend service. Not microservices yet; the contract is what matters now, not the deployment shape.","sidebar":"componentsSidebar"},"data/index":{"id":"data/index","title":"Layer 1 \u2014 Data","description":"Single Postgres instance. One shared database. Tenants isolated by org_id column on every tenant-scoped table \u2014 same as today.","sidebar":"dataSidebar"},"overview/index":{"id":"overview/index","title":"Overview","description":"Stage A is the first step on the path toward the architecture described in the Full Scale version of these docs (use the version dropdown in the navbar to switch). It reshapes the current backend into a clear stack \u2014 domain components, a business logic layer, and a real public API \u2014 with the frontend reduced to a thin client. The database stays as it is. The point isn\'t features; it\'s groundwork \u2014 putting the codebase in a shape where later stages can each focus on one specific piece of the destination instead of fighting the foundation.","sidebar":"overviewSidebar"},"overview/plan":{"id":"overview/plan","title":"Plan","description":"All docs deliverables below live in this docs site, organized by layer.","sidebar":"overviewSidebar"}}}}')}}]);